#include <cstdio>
#include <fcntl.h>
#include <iostream>
#include <sys/stat.h>
#include <unistd.h>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " <file>\n";
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) {
        std::perror("open");
        return 1;
    }

    struct stat info{};
    if (fstat(fd, &info) == -1) {
        std::perror("fstat");
        close(fd);
        return 1;
    }

    std::cout << "size=" << info.st_size << '\n';

    if (close(fd) == -1) {
        std::perror("close");
        return 1;
    }
    return 0;
}
